export const BOOK_METADATA_EXTRACTOR_JS =
  "function extractBookMetadata(html, pageUrl, URLImpl) {\n    const decode = (value) => value.replace(/&(#x[\\da-f]+|#\\d+|amp|quot|apos|lt|gt|nbsp);/gi, (_, entity) => {\n        if (entity[0] === '#') {\n            const code = entity[1].toLowerCase() === 'x'\n                ? parseInt(entity.slice(2), 16)\n                : parseInt(entity.slice(1), 10);\n            return code > 0 && code <= 0x10ffff ? String.fromCodePoint(code) : '';\n        }\n        return ({\n            amp: '&',\n            quot: '\"',\n            apos: \"'\",\n            lt: '<',\n            gt: '>',\n            nbsp: ' ',\n        }[entity.toLowerCase()] || '');\n    });\n    const text = (value) => decode(value.replace(/<[^>]*>/g, ' '))\n        .replace(/\\s+/g, ' ')\n        .trim();\n    const attrs = (tag) => {\n        const result = {};\n        const re = /([\\w:-]+)\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s>]+))/g;\n        let match;\n        while ((match = re.exec(tag)))\n            result[match[1].toLowerCase()] = decode(match[2] ?? match[3] ?? match[4]);\n        return result;\n    };\n    const absolute = (value) => {\n        if (!value?.trim())\n            return '';\n        try {\n            const url = new URLImpl(value, pageUrl);\n            if (/^https?:$/.test(url.protocol)) {\n                url.hash = '';\n                return url.href;\n            }\n        }\n        catch {\n        }\n        return '';\n    };\n    const normalizeTitle = (value) => value\n        .trim()\n        .replace(/^[《〈「]|[》〉」]$/g, '')\n        .replace(/(?:全文阅读|全文閱讀|章节列表|章節列表|最新章节|最新章節|txt下载|TXT下载|目录|目錄)$/, '')\n        .trim();\n    const clean = html\n        .replace(/<!--[\\s\\S]*?-->/g, '')\n        .replace(/<(script|style|iframe|noscript)\\b[^>]*>[\\s\\S]*?<\\/\\1\\s*>/gi, '');\n    const meta = {};\n    for (const tag of clean.match(/<meta\\b[^>]*>/gi) || []) {\n        const a = attrs(tag);\n        const key = a.property || a.name;\n        if (key && a.content)\n            meta[key.toLowerCase()] = a.content.trim();\n    }\n    const result = {\n        metadataLinks: [],\n        metadataRules: {},\n        metadataIssues: [],\n    };\n    const put = (field, value, rule) => {\n        if (field === 'cover' &&\n            value &&\n            /(?:no[_-]?(?:photo|cover)|placeholder|loading|logo)\\./i.test(value)) {\n            if (!result.metadataIssues.includes('placeholder-cover'))\n                result.metadataIssues.push('placeholder-cover');\n            return;\n        }\n        if (value && !result[field]) {\n            result[field] = value;\n            result.metadataRules[field] = rule;\n        }\n    };\n    put('title', meta['og:novel:book_name'], 'meta:book_name');\n    put('author', meta['og:novel:author'] || meta.author, 'meta:author');\n    put('cover', meta['og:image'] ? absolute(meta['og:image']) : '', 'meta:image');\n    put('description', meta['og:description'] || meta.description, 'meta:description');\n    const visit = (value, depth = 0) => {\n        if (!value || depth > 5)\n            return;\n        if (Array.isArray(value)) {\n            value.slice(0, 30).forEach(item => visit(item, depth + 1));\n            return;\n        }\n        if (typeof value !== 'object')\n            return;\n        const types = Array.isArray(value['@type'])\n            ? value['@type']\n            : [value['@type']];\n        if (types.includes('Book')) {\n            const name = typeof value.name === 'string' ? value.name : '';\n            if (result.title && normalizeTitle(result.title) !== normalizeTitle(name))\n                return;\n            put('title', name, 'jsonld:Book');\n            const author = Array.isArray(value.author)\n                ? value.author[0]\n                : value.author;\n            put('author', typeof author === 'string' ? author : author?.name, 'jsonld:Book');\n            const image = Array.isArray(value.image) ? value.image[0] : value.image;\n            put('cover', absolute(typeof image === 'string' ? image : image?.url || ''), 'jsonld:Book');\n            put('description', typeof value.description === 'string' ? value.description : '', 'jsonld:Book');\n        }\n        if (value['@graph'])\n            visit(value['@graph'], depth + 1);\n    };\n    for (const script of html.match(/<script\\b[^>]*type\\s*=\\s*[\"']application\\/ld\\+json[\"'][^>]*>[\\s\\S]*?<\\/script\\s*>/gi) || []) {\n        try {\n            visit(JSON.parse(script.replace(/^<script[^>]*>/i, '').replace(/<\\/script\\s*>$/i, '')));\n        }\n        catch {\n        }\n    }\n    const docTitle = text(/<title\\b[^>]*>([\\s\\S]*?)<\\/title>/i.exec(clean)?.[1] || '').split(/[-_|]/)[0];\n    const h1 = text(/<h1\\b[^>]*>([\\s\\S]*?)<\\/h1>/i.exec(clean)?.[1] || '');\n    put('title', normalizeTitle(h1 || docTitle), 'heading/title');\n    const plain = text(clean);\n    put('author', /作者\\s*[：:]\\s*([^\\s，。|]{1,20})/.exec(plain)?.[1], 'label:author');\n    const stack = [];\n    for (const tag of clean.match(/<\\/?[a-z][^>]*>/gi) || []) {\n        const name = /^<\\/?([\\w-]+)/.exec(tag)?.[1].toLowerCase() || '';\n        if (/^<\\//.test(tag)) {\n            for (let index = stack.length - 1; index >= 0; index--) {\n                if (stack[index].tag === name) {\n                    stack.length = index;\n                    break;\n                }\n            }\n            continue;\n        }\n        const a = attrs(tag);\n        if (name === 'img' && !result.cover) {\n            const context = stack.map(node => node.marker).join(' ');\n            const explicit = /(?:^|\\s)(?:bookdetail|cover|book-cover|fmimg|block_img2)(?:\\s|$)/i.test(context) || a.itemprop === 'image';\n            const named = !!result.title &&\n                normalizeTitle(a.alt || '') === normalizeTitle(result.title);\n            const src = a['data-original'] || a['data-src'] || a.src || '';\n            if (explicit || named)\n                put('cover', absolute(src), explicit ? 'image:book-container' : 'image:title-alt');\n        }\n        if (!/^(?:img|meta|link|br|hr|input|source|area|base|embed|wbr)$/.test(name) &&\n            !/\\/>$/.test(tag))\n            stack.push({ tag: name, marker: `${a.class || ''} ${a.id || ''}` });\n    }\n    const addLink = (href, reason) => {\n        const url = absolute(href);\n        if (url &&\n            url !== absolute(pageUrl) &&\n            !result.metadataLinks.some(link => link.url === url) &&\n            result.metadataLinks.length < 12)\n            result.metadataLinks.push({ url, reason });\n    };\n    for (const tag of clean.match(/<link\\b[^>]*>/gi) || []) {\n        const a = attrs(tag);\n        if (a.rel === 'canonical')\n            addLink(a.href, 'canonical');\n    }\n    const links = /<a\\b([^>]*)>([\\s\\S]*?)<\\/a>/gi;\n    let link;\n    while ((link = links.exec(clean))) {\n        const a = attrs(link[1]);\n        const label = text(link[2]);\n        if (/^(?:查看|进入|進入|全部|完整)?(?:章节|章節)?(?:目录|目錄|章节列表|章節列表)$/.test(label)) {\n            const target = absolute(a.href);\n            if (target &&\n                new URLImpl(target).origin === new URLImpl(pageUrl).origin &&\n                target !== absolute(pageUrl))\n                result.catalogUrl = result.catalogUrl || target;\n        }\n        if (/^(?:返回)?(?:书籍|書籍|本书|本書)?(?:详情|詳情|信息|资料|資料|介绍|介紹|书页|書頁)$/.test(label) ||\n            (!!result.title && normalizeTitle(label) === normalizeTitle(result.title)))\n            addLink(a.href, 'book-link');\n    }\n    return result;\n}";
